package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	s, _ := reader.ReadString('\n')

	var dna string
	for _, c := range s {
		if c == 'A' || c == 'T' || c == 'G' || c == 'C' {
			dna += string(c)
		}
	}

	if len(dna) == 0 {
		fmt.Println(0)
		return
	}

	insertions := 0
	currentRun := 1

	for i := 1; i < len(dna); i++ {
		if dna[i] == dna[i-1] {
			currentRun++
		} else {
			if currentRun%2 == 0 {
				insertions++
			}
			currentRun = 1
		}
	}

	if currentRun%2 == 0 {
		insertions++
	}

	fmt.Println(insertions)
}
